def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_def = sum(1 for a in op if a == 'D')
    my_def = sum(1 for a in my if a == 'D')
    opp_c = n - opp_def

    last_my, last_op = history[-1]

    # Endgame: with a few rounds left, exploit a cooperative partner.
    remaining = 100 - n
    if remaining <= 2:
        if opp_def * 3 <= n:
            return 'D'
        return 'D'

    # Opponent appears to be a persistent defector: defect.
    if opp_def * 2 > n and n >= 6:
        return 'D'

    # If opponent just defected while we cooperated, retaliate once.
    # Then, if opponent returns to cooperation, resume cooperation (forgiveness).
    if last_op == 'D' and last_my == 'C':
        return 'D'

    # If opponent defected and we also defected last round, check if we should
    # try to repair. After a short punishment, cooperate if opponent behaves.
    if last_op == 'D' and last_my == 'D':
        # Count consecutive defections from both sides
        opp_streak = 0
        for a in reversed(op):
            if a == 'D':
                opp_streak += 1
            else:
                break
        my_streak = 0
        for a in reversed(my):
            if a == 'D':
                my_streak += 1
            else:
                break
        # If punishment has been short, try cooperating to restore cooperation.
        if opp_streak <= 1 and my_streak <= 1:
            return 'C'
        if opp_streak >= 3:
            return 'D'
        # After extended mutual defection, try to repair with some probability.
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    if last_op == 'C':
        # If opponent has been overwhelmingly cooperative, mostly cooperate.
        # Occasionally exploit very late but keep mutual cooperation going.
        if opp_c >= n * 0.9 and n >= 30:
            if rng.random() < 0.06:
                return 'D'
            return 'C'
        # If we defected recently and opponent still cooperates, return to
        # cooperation to keep the mutually beneficial relationship going.
        if last_my == 'D':
            return 'C'
        return 'C'

    return 'C'
